	slmCacheMaxStale, err := getEnvInt("NEXUS_SLMCACHE_MAX_STALE", 0)
	if err != nil {
		return cfg, err
	}
	if slmCacheMaxStale < 0 {
		slmCacheMaxStale = 0
	}
	cfg.SLMCacheMaxStale = slmCacheMaxStale

